{
 "command": "cat scripts/backfill_tax.py && ls scripts",
 "description": "Show backfill script and list scripts"
}

{
 "command": "cat src/billing/periods.py; echo \"DATABASE_URL set: ${DATABASE_URL:+yes}\"; echo \"BACKFILL_BATCH=${BACKFILL_BATCH-unset}\"",
 "description": "Show month_window and check env vars"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=${TZ-unset}\"; date +%Z",
 "description": "Run September tax backfill (dry run)"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Rerun September backfill with UTC timezone"
}

{
 "type": "hazard",
 "summary": "Billing scripts using month_window must run with TZ=UTC or they raise RuntimeError",
 "content": "src/billing/periods.py month_window() raises \"period YYYY-MM does not line up with the ledger period table\" unless local time equals UTC, because it compares time.mktime with calendar.timegm. Dev shells may have TZ=Europe/Berlin set. Run scripts like scripts/backfill_tax.py as `TZ=UTC python ...`. Also: backfill_tax.py's default batch (2000, or BACKFILL_BATCH) is above MAX_SAFE_BATCH=500 and exits 3, so pass --batch-size 500 or lower.",
 "physical": [
  "src/billing/periods.py",
  "scripts/backfill_tax.py"
 ],
 "invalidated_by": [
  "src/billing/periods.py"
 ],
 "epistemic": "fact"
}
